/**
 * PRIVATE DATA BUNDLE (encrypted).
 *
 * Children's personal data used to be readable in this public file set (survey answers, teacher comments for parents,
 * birthdays). It is now shipped only as AES-256-GCM ciphertext. The key lives in the Supabase table private_bundle_key,
 * which only a signed-in teacher can read (row level security: is_teacher()). After teacher sign-in the app calls
 * EAAPrivate.load(); the key is fetched, the bundle is decrypted in memory and is never written to browser storage.
 * Without a teacher session every get() returns null and the pages that need it say so.
 *
 * Sections: survey (All About Me answers by pupil id), parentNotes (school number -> {en, tr}), birthdays ([{id, md}]).
 */
(function (root) {
  'use strict';

  var ENCRYPTED_BUNDLE = '';

  var DATA = null;
  var loading = null;

  function b64ToBytes(b64) {
    var bin = atob(b64), out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function getClient() {
    var A = root.AdventureSupabase;
    if (!A || !A.isConfigured) return null;
    try { return A.client || (A._ensureClient && A._ensureClient()) || null; } catch (e) { return null; }
  }

  async function decrypt(keyB64) {
    if (!root.crypto || !root.crypto.subtle) throw new Error('Secure browser context needed (https).');
    var all = b64ToBytes(ENCRYPTED_BUNDLE);
    var key = await root.crypto.subtle.importKey('raw', b64ToBytes(keyB64), { name: 'AES-GCM' }, false, ['decrypt']);
    var plain = await root.crypto.subtle.decrypt({ name: 'AES-GCM', iv: all.slice(0, 12) }, key, all.slice(12));
    return JSON.parse(new TextDecoder().decode(plain));
  }

  /* Fetch the key (teacher session only) and decrypt. Safe to call many times; resolves true when the data is available. */
  function load(opts) {
    if (DATA) return Promise.resolve(true);
    if (loading) return loading;
    var client = (opts && opts.client) || getClient();
    if (!client) return Promise.resolve(false);
    loading = (async function () {
      try {
        var res = await client.from('private_bundle_key').select('key').eq('id', 1).maybeSingle();
        if (res.error || !res.data || !res.data.key) return false;   // no teacher session: row level security returns nothing
        DATA = await decrypt(res.data.key);
        try { root.dispatchEvent(new CustomEvent('eaa:private-loaded')); } catch (e) { /* optional */ }
        return true;
      } catch (err) {
        if (root.console && console.warn) console.warn('[EAAPrivate] not loaded:', err && err.message);
        return false;
      } finally { loading = null; }
    })();
    return loading;
  }

  root.EAAPrivate = {
    load: load,
    isLoaded: function () { return !!DATA; },
    get: function (section) { return (DATA && DATA[section]) || null; },
    _decryptWith: decrypt   // test hook
  };
})(typeof window !== 'undefined' ? window : this);
